bool PolyData_ComboEffectsAsDamageEffect(
  const PolyData_ComboRecord_t* record, size_t at, PolyData_StructDamageEffect* out)
{
  const struct PolyData_ComboRecord_t_effects_entry* entry = &record->effects[at];

  if (entry->type != 1) {
    return false;
  }

  out->chance = entry->chance;
  out->damage = entry->damage;
  out->pierces = entry->pierces;
  out->element_id = entry->element_id;
  out->element_by_element_id = entry->element_by_element_id;
  return true;
}

bool PolyData_ComboEffectsAsHealEffect(
  const PolyData_ComboRecord_t* record, size_t at, PolyData_StructHealEffect* out)
{
  const struct PolyData_ComboRecord_t_effects_entry* entry = &record->effects[at];

  if (entry->type != 2) {
    return false;
  }

  out->chance = entry->chance;
  out->amount = entry->amount;
  out->band = entry->band;
  return true;
}

bool PolyData_ComboEffectsAsNoEffect(
  const PolyData_ComboRecord_t* record, size_t at, PolyData_StructNoEffect* out)
{
  const struct PolyData_ComboRecord_t_effects_entry* entry = &record->effects[at];

  if (entry->type != 3) {
    return false;
  }

  out->chance = entry->chance;
  return true;
}
